theorem isUnit_of_certificate_of_dvd
    {eps k lam : K} {h g f : K[X]} {m : ℕ} {P : K[X][Y]}
    {H B : (FractionRing K[X])[X]}
    (cert : Certificate eps k lam h g f P H B m)
    (heps : eps ≠ 0) (hk : k ≠ 0) (hh : h ≠ 0) (hg : h ∣ g) :
    IsUnit h

theorem quadraticInYMap_eq_zeroSlopeNormalFormMap {a b c e f : K[X]}
    {eta delta gamma : K}
    (ha : a = 0) (hb : b = C eta) (he : e = 0)
    (hf : f = C delta * X + C gamma) :
    quadraticInYMap a b c e f = zeroSlopeNormalFormMap eta delta gamma c

theorem h_dvd_g_of_certificate
    {eps k lam : K} {h g f : K[X]} {P : K[X][Y]}
    {H B : (FractionRing K[X])[X]} {m : ℕ}
    (heps : eps ≠ 0) (hh : h ≠ 0)
    (cert : Certificate eps k lam h g f P H B m) :
    h ∣ g

theorem eval_discriminant_of_eq_affine {eps A B x : K} {g f : K[X]}
    (hDelta : discriminant eps g f = C A * X + C B) :
    (discriminant eps g f).eval x = A * x + B
